import math
from numbers import Real


class RegionAccumulator:
    def __init__(self, grid):
        if not isinstance(grid, list):
            raise TypeError("grid must be a list")
        width = None
        for row in grid:
            if not isinstance(row, list):
                raise TypeError("rows must be lists")
            if width is None:
                width = len(row)
            elif len(row) != width:
                raise ValueError("grid must be rectangular")
            for value in row:
                if isinstance(value, bool) or not isinstance(value, Real):
                    raise TypeError("cells must be real numbers")
                if not math.isfinite(value):
                    raise ValueError("cells must be finite")
        self._height = len(grid)
        self._width = 0 if width is None else width
        table = [[0 for _ in range(self._width + 1)] for _ in range(self._height + 1)]
        for y, row in enumerate(grid, 1):
            running = 0
            for x, value in enumerate(row, 1):
                running += value
                table[y][x] = table[y - 1][x] + running
        self._prefix = tuple(tuple(row) for row in table)

    def _clipped(self, top, left, bottom, right):
        values = (top, left, bottom, right)
        if any(isinstance(v, bool) or not isinstance(v, int) for v in values):
            raise TypeError("coordinates must be integers")
        if top > bottom or left > right:
            raise ValueError("rectangle bounds are reversed")
        return (max(0, min(self._height, top)),
                max(0, min(self._width, left)),
                max(0, min(self._height, bottom)),
                max(0, min(self._width, right)))

    def rectangle_total(self, top, left, bottom, right):
        top, left, bottom, right = self._clipped(top, left, bottom, right)
        if top >= bottom or left >= right:
            return 0
        p = self._prefix
        return p[bottom][right] - p[top][right] - p[bottom][left] + p[top][left]

    def rectangle_mean(self, top, left, bottom, right):
        clipped = self._clipped(top, left, bottom, right)
        top2, left2, bottom2, right2 = clipped
        count = max(0, bottom - top) * max(0, right - left)
        if count == 0:
            return 0.0
        return self.rectangle_total(*clipped) / count

    def prefix_snapshot(self):
        return self._prefix

